// Kova runtime: the small piece of C glued to every executable (`kova build`).
// Messages must be identical to the interpreter's (src/kir.rs, `fault_text`).
// Its texts come from `locales/*.kova`, generated by `kova build` (src/locale.rs, `c_texts`).

#include <ctype.h>
#include <errno.h>
#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <time.h>
#ifdef _WIN32
// Windows: its own functions for files, time and the command line (PLAN Part 4 "Windows").
#define WIN32_LEAN_AND_MEAN
#define NOMINMAX
#include <windows.h>
#include <shellapi.h>
#include <direct.h>
#include <fcntl.h>
#include <io.h>
#include <process.h>
#ifdef _MSC_VER
#pragma comment(lib, "shell32.lib") // CommandLineToArgvW
#endif
#else
#include <dirent.h>
#include <unistd.h>
#endif

// Provided by the code generated by Cranelift (src/codegen.rs).
// The source files' paths (in the generated texts.c): a site packs a file number and a line
// (`Loc::packed` in src/kir.rs).
extern const char *const kova_files[];
void kova_main(void);

// Provided by the generated texts: `kova_nb_texts` texts per language, in the order of
// `locale::RUNTIME`; `kova_forced_lang` = the `header`'s language, or -1.
extern const int kova_nb_langs, kova_nb_texts, kova_forced_lang;
extern const char *const kova_langs[];
extern const char *const kova_texts[];

// The language: the `header`'s, otherwise the first non-empty variable among KOVA_LANG,
// LC_ALL, LC_MESSAGES, LANG (`fr_FR.UTF-8` → `fr`), otherwise English. Same rule as
// `system` in src/locale.rs.
static int language(void) {
    if (kova_forced_lang >= 0) return kova_forced_lang;
    static const char *const vars[] = {"KOVA_LANG", "LC_ALL", "LC_MESSAGES", "LANG"};
    for (int v = 0; v < 4; v++) {
        const char *value = getenv(vars[v]);
        if (!value || !*value) continue;
        size_t n = strcspn(value, "_.@-");
        for (int l = 0; l < kova_nb_langs; l++) {
            const char *code = kova_langs[l];
            size_t i = 0;
            while (i < n && code[i] && tolower((unsigned char)value[i]) == code[i]) i++;
            if (i == n && !code[i]) return l;
        }
        return 0;
    }
    return 0;
}

// Numbers of the texts in `locale::RUNTIME` (src/locale.rs), checked by a test there.
enum { LEAK_ALLOCATED = 7, LEAK_LIVE = 8, FAULT_INDEX = 9 };

static const char *text(int64_t i) {
    return kova_texts[language() * kova_nb_texts + i];
}

// `d + 1` on the last digit (digits 0-9), with carry. Returns 1 if the exponent grows.
static int plus_one(char *ch, int n) {
    for (int i = n - 1; i >= 0; i--) {
        if (ch[i] < 9) { ch[i]++; return 0; }
        ch[i] = 0;
    }
    ch[0] = 1; // 999 → 100
    return 1;
}

// True if the digits `ch` (n digits, exponent e) give back exactly a.
static int reads_back(const char *ch, int n, int e, double a) {
    char buf[40];
    int k = 0;
    buf[k++] = '0' + ch[0];
    buf[k++] = '.';
    for (int i = 1; i < n; i++) buf[k++] = '0' + ch[i];
    snprintf(buf + k, sizeof buf - k, "e%d", e);
    return strtod(buf, NULL) == a;
}

// The shortest digits of a (> 0) that give back a: same computation as
// `shortest` in src/kir.rs. Returns the number of digits; *e = exponent of the first one.
static int shortest(double a, char *res, int *e) {
    static char buf[1000];
    snprintf(buf, sizeof buf, "%.800e", a); // all the exact digits (glibc)
    char exact[820];
    int n = 0;
    char *c = buf;
    for (; *c != 'e'; c++)
        if (*c != '.') exact[n++] = *c - '0';
    *e = atoi(c + 1);
    while (n > 1 && exact[n - 1] == 0) n--;

    for (int p = 1; p <= 17; p++) {
        if (n <= p) { memcpy(res, exact, n); return n; }
        // The two p-digit numbers around a: `low` (truncated) and `high`.
        char low[17], high[17];
        memcpy(low, exact, p);
        memcpy(high, exact, p);
        int e_high = *e + plus_one(high, p);
        int after = 0;
        for (int i = p + 1; i < n; i++) after |= exact[i];
        int round_up = exact[p] > 5 || (exact[p] == 5 && (after || low[p - 1] % 2 == 1));
        char *closer = round_up ? high : low, *other = round_up ? low : high;
        int e_near = round_up ? e_high : *e, e_far = round_up ? *e : e_high;
        char *winner = NULL;
        int e_winner = 0;
        if (reads_back(closer, p, e_near, a)) { winner = closer; e_winner = e_near; }
        else if (reads_back(other, p, e_far, a)) { winner = other; e_winner = e_far; }
        if (winner) {
            while (p > 1 && winner[p - 1] == 0) p--;
            memcpy(res, winner, p);
            *e = e_winner;
            return p;
        }
    }
    abort(); // 17 digits are always enough
}

// Where a value is written: a FILE (`print`), or a growing text (`"{x}"`) when `f` is NULL.
typedef struct {
    FILE *f;
    char *bytes;
    size_t n, room;
} Out;

static void put(Out *o, const char *s, size_t n) {
    if (o->f) {
        fwrite(s, 1, n, o->f);
        return;
    }
    if (o->n + n > o->room) {
        o->room = (o->n + n) * 2;
        if (!(o->bytes = realloc(o->bytes, o->room))) abort();
    }
    memcpy(o->bytes + o->n, s, n);
    o->n += n;
}

static void put_text(Out *o, const char *s) { put(o, s, strlen(s)); }

static void put_char(Out *o, int c) {
    char b = (char)c;
    put(o, &b, 1);
}

static void put_int(Out *o, int64_t v) {
    char buf[24];
    put(o, buf, snprintf(buf, sizeof buf, "%lld", (long long)v));
}

// A Float like `float_text` in src/kir.rs: `3.0`, `0.30000000000000004`, `1e16`, `NaN`.
static void write_float(Out *o, double x) {
    if (isnan(x)) { put_text(o, "NaN"); return; } // printf would write `-nan` depending on the sign
    if (isinf(x)) { put_text(o, x > 0 ? "inf" : "-inf"); return; }
    if (signbit(x)) put_char(o, '-'); // keeps the sign of -0.0
    double a = fabs(x);
    char ch[17];
    int exp = 0, n = 1;
    if (a == 0.0) ch[0] = 0;
    else n = shortest(a, ch, &exp);
    for (int i = 0; i < n; i++) ch[i] += '0';

    if (a == 0.0 || (a >= 1e-4 && a < 1e16)) {
        if (exp >= 0) {
            for (int i = 0; i <= exp; i++) put_char(o, i < n ? ch[i] : '0');
            put_char(o, '.');
            if (n > exp + 1) put(o, ch + exp + 1, n - exp - 1);
            else put_char(o, '0');
        } else {
            put_text(o, "0.");
            for (int i = 0; i < -exp - 1; i++) put_char(o, '0');
            put(o, ch, n);
        }
    } else {
        put_char(o, ch[0]);
        if (n > 1) { put_char(o, '.'); put(o, ch + 1, n - 1); }
        put_char(o, 'e');
        put_int(o, exp);
    }
}

// A Char (Unicode code point) in UTF-8.
static void write_char(Out *o, uint32_t c) {
    if (c < 0x80) {
        put_char(o, c);
    } else if (c < 0x800) {
        put_char(o, 0xC0 | c >> 6);
        put_char(o, 0x80 | (c & 0x3F));
    } else if (c < 0x10000) {
        put_char(o, 0xE0 | c >> 12);
        put_char(o, 0x80 | (c >> 6 & 0x3F));
        put_char(o, 0x80 | (c & 0x3F));
    } else {
        put_char(o, 0xF0 | c >> 18);
        put_char(o, 0x80 | (c >> 12 & 0x3F));
        put_char(o, 0x80 | (c >> 6 & 0x3F));
        put_char(o, 0x80 | (c & 0x3F));
    }
}

// ---- Strings ----
// A String is a block `length + bytes` (UTF-8, no final 0), passed around by its address.
// 0 = no String: freeing it does nothing (a moved variable holds 0, src/kir.rs).

typedef struct {
    int64_t length;
    char bytes[];
} String;

static int64_t allocated, live;

static String *new_string(int64_t n) {
    String *s = malloc(sizeof(String) + n);
    if (!s) abort();
    s->length = n;
    allocated++;
    live++;
    return s;
}

int64_t kova_str_new(const char *bytes, int64_t n) {
    String *s = new_string(n);
    memcpy(s->bytes, bytes, n);
    return (int64_t)s;
}

void kova_str_free(int64_t s) {
    if (!s) return;
    free((String *)s);
    live--;
}

int64_t kova_str_concat(int64_t a, int64_t b) {
    String *x = (String *)a, *y = (String *)b;
    String *s = new_string(x->length + y->length);
    memcpy(s->bytes, x->bytes, x->length);
    memcpy(s->bytes + x->length, y->bytes, y->length);
    return (int64_t)s;
}

int64_t kova_str_eq(int64_t a, int64_t b) {
    String *x = (String *)a, *y = (String *)b;
    return x->length == y->length && memcmp(x->bytes, y->bytes, x->length) == 0;
}

// A number for the text (FNV-1a), the same as `StrOp::Hash` in src/interp.rs; 0 for no String.
int64_t kova_str_hash(int64_t a) {
    String *x = (String *)a;
    uint64_t h = 0xcbf29ce484222325u;
    if (!x) return 0;
    for (int64_t i = 0; i < x->length; i++) h = (h ^ (uint8_t)x->bytes[i]) * 0x100000001b3u;
    return (int64_t)h;
}

// `a < b`: the order of the bytes, which is the order of the characters' codes in UTF-8
// (same as Rust's `str` order, src/interp.rs).
int64_t kova_str_less(int64_t a, int64_t b) {
    String *x = (String *)a, *y = (String *)b;
    int64_t n = x->length < y->length ? x->length : y->length;
    int c = memcmp(x->bytes, y->bytes, n);
    return c < 0 || (c == 0 && x->length < y->length);
}

// The number of characters: the bytes that don't continue a UTF-8 character (10xxxxxx).
int64_t kova_str_length(int64_t a) {
    String *x = (String *)a;
    int64_t n = 0;
    for (int64_t i = 0; i < x->length; i++) n += ((unsigned char)x->bytes[i] & 0xC0) != 0x80;
    return n;
}

// 0 (no String: a field of another variant of an enum) is copied as 0.
int64_t kova_str_clone(int64_t a) {
    if (!a) return 0;
    String *x = (String *)a;
    return kova_str_new(x->bytes, x->length);
}

// `s.to_int`: an optional `-` then digits only, within the range of an Int
// (same rule as `parse_int` in src/kir.rs). Returns 1 and sets `*out`, or returns 0.
static int parse_int(int64_t a, int64_t *out) {
    String *x = (String *)a;
    int64_t i = 0, n = x->length;
    int negative = n > 0 && x->bytes[0] == '-';
    if (negative) i = 1;
    if (i == n) return 0;
    uint64_t v = 0, limit = negative ? (uint64_t)INT64_MAX + 1 : (uint64_t)INT64_MAX;
    for (; i < n; i++) {
        unsigned char c = x->bytes[i];
        if (c < '0' || c > '9') return 0;
        if (v > (limit - (c - '0')) / 10) return 0;
        v = v * 10 + (c - '0');
    }
    *out = negative ? (int64_t)(0 - v) : (int64_t)v;
    return 1;
}

int64_t kova_str_is_int(int64_t a) {
    int64_t v;
    return parse_int(a, &v);
}

int64_t kova_str_to_int(int64_t a) {
    int64_t v = 0;
    parse_int(a, &v);
    return v;
}

// ---- BigInt: a String holding its decimal text, like "-42" (src/bigint.rs does the same) ----
// ponytail: one decimal digit at a time, O(n²) for `*` and `/`; limbs of 9 digits when big
// numbers get thousands of digits long.

// The digits, the units first, in a buffer of `size` bytes (zeros after them); the sign in *neg.
static unsigned char *digits(String *s, int64_t size, int *neg, int64_t *n) {
    *neg = s->length > 0 && s->bytes[0] == '-';
    *n = s->length - *neg;
    unsigned char *d = calloc(size > *n ? size : *n, 1);
    if (!d) abort();
    for (int64_t i = 0; i < *n; i++) d[i] = s->bytes[s->length - 1 - i] - '0';
    return d;
}

static int64_t trim(unsigned char *d, int64_t n) {
    while (n > 1 && d[n - 1] == 0) n--;
    return n;
}

// The text of `n` digits (units first, freed here): no leading zeros, "0" never negative.
static int64_t big_text(int neg, unsigned char *d, int64_t n) {
    n = trim(d, n);
    int zero = n == 1 && d[0] == 0;
    neg = neg && !zero;
    String *s = new_string(n + neg);
    if (neg) s->bytes[0] = '-';
    for (int64_t i = 0; i < n; i++) s->bytes[neg + i] = d[n - 1 - i] + '0';
    free(d);
    return (int64_t)s;
}

static int compare(const unsigned char *a, int64_t na, const unsigned char *b, int64_t nb) {
    if (na != nb) return na < nb ? -1 : 1;
    for (int64_t i = na - 1; i >= 0; i--)
        if (a[i] != b[i]) return a[i] < b[i] ? -1 : 1;
    return 0;
}

// a := a - b, with a >= b; the new length.
static int64_t minus(unsigned char *a, int64_t na, const unsigned char *b, int64_t nb) {
    int borrow = 0;
    for (int64_t i = 0; i < na; i++) {
        int d = a[i] - (i < nb ? b[i] : 0) - borrow;
        borrow = d < 0;
        a[i] = d < 0 ? d + 10 : d;
    }
    return trim(a, na);
}

// |a| + |b| or |a| - |b| (`subtract`), with the sign of the result.
static int64_t add_signed(int64_t a, int na_neg, int64_t b, int nb_neg) {
    String *x = (String *)a, *y = (String *)b;
    int xn, yn;
    int64_t nx, ny;
    int64_t size = (x->length > y->length ? x->length : y->length) + 1;
    unsigned char *da = digits(x, size, &xn, &nx), *db = digits(y, size, &yn, &ny);
    xn ^= na_neg;
    yn ^= nb_neg;
    int64_t n;
    int neg;
    if (xn == yn) {
        int carry = 0;
        for (int64_t i = 0; i < size; i++) {
            int s = da[i] + db[i] + carry;
            da[i] = s % 10;
            carry = s / 10;
        }
        n = size;
        neg = xn;
    } else if (compare(da, trim(da, nx), db, trim(db, ny)) < 0) {
        n = minus(db, ny, da, nx);
        free(da);
        return big_text(yn, db, n);
    } else {
        n = minus(da, nx, db, ny);
        neg = xn;
    }
    free(db);
    return big_text(neg, da, n);
}

int64_t kova_big_add(int64_t a, int64_t b) { return add_signed(a, 0, b, 0); }
int64_t kova_big_sub(int64_t a, int64_t b) { return add_signed(a, 0, b, 1); }

int64_t kova_big_mul(int64_t a, int64_t b) {
    int xn, yn;
    int64_t nx, ny;
    unsigned char *da = digits((String *)a, 1, &xn, &nx), *db = digits((String *)b, 1, &yn, &ny);
    uint32_t *sum = calloc(nx + ny, sizeof(uint32_t));
    unsigned char *out = malloc(nx + ny);
    if (!sum || !out) abort();
    for (int64_t i = 0; i < nx; i++)
        for (int64_t j = 0; j < ny; j++) sum[i + j] += da[i] * db[j];
    uint32_t carry = 0;
    for (int64_t i = 0; i < nx + ny; i++) {
        sum[i] += carry;
        carry = sum[i] / 10;
        out[i] = sum[i] % 10;
    }
    free(da);
    free(db);
    free(sum);
    return big_text(xn != yn, out, nx + ny);
}

// Long division, as on paper; `b` is not 0 (checked before). `quotient`: a / b, else a % b.
static int64_t divide(int64_t a, int64_t b, int quotient) {
    int xn, yn;
    int64_t nx, ny;
    unsigned char *da = digits((String *)a, 1, &xn, &nx), *db = digits((String *)b, 1, &yn, &ny);
    ny = trim(db, ny);
    unsigned char *q = calloc(nx, 1), *r = calloc(nx + 2, 1);
    if (!q || !r) abort();
    int64_t nr = 1;
    for (int64_t i = nx - 1; i >= 0; i--) {
        memmove(r + 1, r, nr);
        r[0] = da[i];
        nr = trim(r, nr + 1);
        while (compare(r, nr, db, ny) >= 0) {
            nr = minus(r, nr, db, ny);
            q[i]++;
        }
    }
    free(da);
    free(db);
    if (quotient) {
        free(r);
        return big_text(xn != yn, q, nx);
    }
    free(q);
    return big_text(xn, r, nr);
}

int64_t kova_big_div(int64_t a, int64_t b) { return divide(a, b, 1); }
int64_t kova_big_rem(int64_t a, int64_t b) { return divide(a, b, 0); }

int64_t kova_big_less(int64_t a, int64_t b) {
    int xn, yn;
    int64_t nx, ny;
    unsigned char *da = digits((String *)a, 1, &xn, &nx), *db = digits((String *)b, 1, &yn, &ny);
    int c = compare(da, nx, db, ny);
    free(da);
    free(db);
    if (xn != yn) return xn;
    return xn ? c > 0 : c < 0;
}

// ---- Files and input ----

// Valid UTF-8, as strict as Rust's `String::from_utf8` (src/interp.rs): no overlong form,
// no surrogate, nothing above U+10FFFF.
static int valid_utf8(const unsigned char *b, int64_t n) {
    for (int64_t i = 0; i < n;) {
        unsigned char c = b[i];
        int k;
        uint32_t v, min;
        if (c < 0x80) { i++; continue; }
        else if ((c & 0xE0) == 0xC0) { k = 1; v = c & 0x1F; min = 0x80; }
        else if ((c & 0xF0) == 0xE0) { k = 2; v = c & 0x0F; min = 0x800; }
        else if ((c & 0xF8) == 0xF0) { k = 3; v = c & 0x07; min = 0x10000; }
        else return 0;
        if (i + k >= n) return 0;
        for (int j = 1; j <= k; j++) {
            if ((b[i + j] & 0xC0) != 0x80) return 0;
            v = v << 6 | (b[i + j] & 0x3F);
        }
        if (v < min || v > 0x10FFFF || (v >= 0xD800 && v <= 0xDFFF)) return 0;
        i += k + 1;
    }
    return 1;
}

// What `path` names: 0 nothing (errno says why), 1 a file, 2 a directory.
// Windows wants paths in UTF-16 (`wide`), not in UTF-8.
#ifdef _WIN32
static wchar_t *wide(const char *s) {
    int n = MultiByteToWideChar(CP_UTF8, 0, s, -1, NULL, 0);
    wchar_t *w = malloc(n * sizeof(wchar_t));
    if (!w) abort();
    MultiByteToWideChar(CP_UTF8, 0, s, -1, w, n);
    return w;
}

static int kind_of(const char *path) {
    struct _stat64 st;
    wchar_t *w = wide(path);
    int r = _wstat64(w, &st);
    free(w);
    return r != 0 ? 0 : st.st_mode & _S_IFDIR ? 2 : 1;
}

static FILE *open_file(const char *path, const char *how) {
    wchar_t *w = wide(path), *h = wide(how);
    FILE *f = _wfopen(w, h);
    free(w);
    free(h);
    return f;
}

static int make_one(const char *path) {
    wchar_t *w = wide(path);
    int r = _wmkdir(w);
    free(w);
    return r;
}

static int remove_one(const char *path) {
    wchar_t *w = wide(path);
    int r = _wremove(w);
    free(w);
    return r;
}
#else
static int kind_of(const char *path) {
    struct stat st;
    return stat(path, &st) != 0 ? 0 : S_ISDIR(st.st_mode) ? 2 : 1;
}

static FILE *open_file(const char *path, const char *how) { return fopen(path, how); }
static int make_one(const char *path) { return mkdir(path, 0777); }
static int remove_one(const char *path) { return unlink(path); }
#endif

// `read_file(path)`: the file's text as a String, or minus the failure's number
// (1 NotFound, 2 Denied, 3 IsDirectory, 4 NotText, 5 Other: the variants of `IoError`, src/types.rs).
int64_t kova_read_file(int64_t p) {
    String *x = (String *)p;
    char *path = malloc(x->length + 1);
    if (!path) abort();
    memcpy(path, x->bytes, x->length);
    path[x->length] = 0;
    int64_t failure = 0, kind;
    FILE *f = NULL;
    if (memchr(x->bytes, 0, x->length)) failure = 5;
    else if (!(kind = kind_of(path))) failure = errno == ENOENT || errno == ENOTDIR ? 1 : errno == EACCES || errno == EPERM ? 2 : 5;
    else if (kind == 2) failure = 3;
    else if (!(f = open_file(path, "rb"))) failure = errno == EACCES || errno == EPERM ? 2 : 5;
    free(path);
    if (failure) return -failure;
    // Read in growing pieces: the size given by `stat` may be wrong (`/proc`, a pipe).
    int64_t size = 0, room = 4096;
    char *bytes = malloc(room);
    if (!bytes) abort();
    size_t got;
    while ((got = fread(bytes + size, 1, room - size, f)) > 0) {
        size += got;
        if (size == room && !(bytes = realloc(bytes, room *= 2))) abort();
    }
    int broken = ferror(f);
    fclose(f);
    int64_t result = broken ? -5 : !valid_utf8((unsigned char *)bytes, size) ? -4 : kova_str_new(bytes, size);
    free(bytes);
    return result;
}

// `read_line`: the next line of the input without its end (`\n` or `\r\n`),
// 0 at the end of the input, -1 if the line is not UTF-8 (src/kir.rs stops the program).
int64_t kova_read_line(void) {
    fflush(stdout);
    char *line = NULL;
    size_t n = 0, room = 0;
    int c = getc(stdin);
    if (c == EOF) return 0;
    for (; c != EOF && c != '\n'; c = getc(stdin)) {
        if (n == room && !(line = realloc(line, room = room * 2 + 64))) abort();
        line[n++] = (char)c;
    }
    if (n > 0 && line[n - 1] == '\r') n--;
    int64_t result = valid_utf8((unsigned char *)line, n) ? kova_str_new(line, n) : -1;
    free(line);
    return result;
}

// ---- Lists ----
// A List is a fixed block (so its address never changes) pointing to its elements,
// `width` slots each, one after the other. 0 = no List (moved): freeing it does nothing.
// A Map or a Set also has an `index` (a table of positions, made by `find_in_index` in
// src/kir.rs): freed with it; `unindex` takes a removed element out of it.

typedef struct {
    int64_t length, capacity, width;
    int64_t *slots;
    int64_t index;
} List;

int64_t kova_list_new(int64_t width) {
    List *l = calloc(1, sizeof(List));
    if (!l) abort();
    l->width = width;
    allocated++;
    live++;
    return (int64_t)l;
}

int64_t kova_list_length(int64_t l) {
    return l ? ((List *)l)->length : 0;
}

void kova_fault(int64_t fault, int64_t line, int64_t col);

void kova_list_check(int64_t l, int64_t i, int64_t line, int64_t col) {
    if (i < 0 || i >= ((List *)l)->length) kova_fault(FAULT_INDEX, line, col);
}

int64_t kova_list_load(int64_t l, int64_t i, int64_t k) {
    List *x = (List *)l;
    return x->slots[i * x->width + k];
}

void kova_list_store(int64_t l, int64_t i, int64_t k, int64_t v) {
    List *x = (List *)l;
    x->slots[i * x->width + k] = v;
}

// One more element at the end (slots set to 0); returns its index.
int64_t kova_list_grow(int64_t l) {
    List *x = (List *)l;
    if (x->length == x->capacity) {
        x->capacity = x->capacity ? 2 * x->capacity : 4;
        x->slots = realloc(x->slots, x->capacity * x->width * sizeof(int64_t) + 1);
        if (!x->slots) abort();
    }
    memset(x->slots + x->length * x->width, 0, x->width * sizeof(int64_t));
    return x->length++;
}

// Element `i` of a Map or a Set goes: out of its index (its place emptied, the next keys moved
// back towards their own place, as linear probing needs), and the positions after it move
// back by one. The same as `unindex` in src/interp.rs.
static void unindex(int64_t index, int64_t i) {
    int64_t *s = ((List *)index)->slots, cap = ((List *)index)->length - 1, j = 0;
    if (i >= s[0]) return; // not in the index yet
    for (int64_t k = 1; k <= cap; k++) {
        if (s[2 * k + 1] == i + 1) j = k;
        if (s[2 * k + 1] > i + 1) s[2 * k + 1]--;
    }
    s[0]--;
    for (int64_t k = j % cap + 1; s[2 * k + 1]; k = k % cap + 1) {
        int64_t home = s[2 * k] % cap + 1;
        // `k` stays if its own place lies after `j` (cyclically, up to `k`).
        if (j < k ? (j < home && home <= k) : (j < home || home <= k)) continue;
        s[2 * j] = s[2 * k];
        s[2 * j + 1] = s[2 * k + 1];
        j = k;
    }
    s[2 * j] = s[2 * j + 1] = 0;
}

void kova_list_remove(int64_t l, int64_t i) {
    List *x = (List *)l;
    int64_t w = x->width;
    if (x->index) unindex(x->index, i);
    memmove(x->slots + i * w, x->slots + (i + 1) * w, (x->length - i - 1) * w * sizeof(int64_t));
    x->length--;
}

void kova_list_free(int64_t l) {
    if (!l) return;
    kova_list_free(((List *)l)->index);
    free(((List *)l)->slots);
    free((List *)l);
    live--;
}

int64_t kova_list_index(int64_t l) {
    return l ? ((List *)l)->index : 0;
}

void kova_list_set_index(int64_t l, int64_t index) {
    ((List *)l)->index = index;
}

// ---- Files and directories: 0 (or a new value) when it works, else minus the failure, numbered
// like `IoError` (src/types.rs `io_error`) and like src/interp.rs `failure`. ----

// `errno` as an `IoError`: 1 NotFound, 2 Denied, 3 IsDirectory, 5 Other.
static int64_t failure(void) {
    return errno == ENOENT || errno == ENOTDIR ? 1 : errno == EACCES || errno == EPERM || errno == EROFS ? 2 : errno == EISDIR ? 3 : 5;
}

// The path as a C text (to free), or NULL if it holds a 0 byte (no file has such a name).
static char *c_path(int64_t p) {
    String *x = (String *)p;
    if (memchr(x->bytes, 0, x->length)) return NULL;
    char *path = malloc(x->length + 1);
    if (!path) abort();
    memcpy(path, x->bytes, x->length);
    path[x->length] = 0;
    return path;
}

static int64_t put_file(int64_t p, int64_t t, const char *how) {
    char *path = c_path(p);
    if (!path) return -5;
    String *text = (String *)t;
    int64_t result = 0;
    FILE *f = NULL;
    if (kind_of(path) == 2) result = -3;
    else if (!(f = open_file(path, how))) result = -failure();
    else if (fwrite(text->bytes, 1, text->length, f) != (size_t)text->length) result = -5;
    if (f && fclose(f) != 0 && !result) result = -5;
    free(path);
    return result;
}

int64_t kova_write_file(int64_t p, int64_t t) { return put_file(p, t, "wb"); }
int64_t kova_append_file(int64_t p, int64_t t) { return put_file(p, t, "ab"); }

int64_t kova_exists(int64_t p) {
    char *path = c_path(p);
    int64_t there = path && kind_of(path);
    free(path);
    return there;
}

static int by_bytes(const void *a, const void *b) {
    String *x = *(String *const *)a, *y = *(String *const *)b;
    int64_t n = x->length < y->length ? x->length : y->length;
    int c = memcmp(x->bytes, y->bytes, n);
    return c ? c : (x->length > y->length) - (x->length < y->length);
}


// Reading a directory: `read_dir` gives each name in UTF-8 (an empty one if Windows' name is
// not valid UTF-16), then NULL.
#ifdef _WIN32
#define SLASH '\\'
typedef struct {
    HANDLE h;
    WIN32_FIND_DATAW e;
    int read;
    char name[MAX_PATH * 3 + 1];
} Dir;

static Dir *open_dir(const char *path) {
    size_t n = strlen(path);
    char *pattern = malloc(n + 3);
    if (!pattern) abort();
    memcpy(pattern, path, n);
    memcpy(pattern + n, "\\*", 3);
    wchar_t *w = wide(pattern);
    free(pattern);
    Dir *d = calloc(1, sizeof(Dir));
    if (!d) abort();
    d->h = FindFirstFileW(w, &d->e);
    free(w);
    if (d->h != INVALID_HANDLE_VALUE) return d;
    DWORD e = GetLastError();
    errno = e == ERROR_FILE_NOT_FOUND || e == ERROR_PATH_NOT_FOUND || e == ERROR_DIRECTORY ? ENOENT : e == ERROR_ACCESS_DENIED ? EACCES : EIO;
    free(d);
    return NULL;
}

static const char *read_dir(Dir *d) {
    if (d->read++ && !FindNextFileW(d->h, &d->e)) return NULL;
    if (!WideCharToMultiByte(CP_UTF8, WC_ERR_INVALID_CHARS, d->e.cFileName, -1, d->name, sizeof d->name, NULL, NULL)) d->name[0] = 0;
    return d->name;
}

static void close_dir(Dir *d) {
    FindClose(d->h);
    free(d);
}
#else
#define SLASH '/'
typedef DIR Dir;
static Dir *open_dir(const char *path) { return opendir(path); }
static const char *read_dir(Dir *d) {
    struct dirent *e = readdir(d);
    return e ? e->d_name : NULL;
}
static void close_dir(Dir *d) { closedir(d); }
#endif

// The names in a directory (without `.` and `..`), in the order of their bytes: the system
// gives them in no particular order.
int64_t kova_list_dir(int64_t p) {
    char *path = c_path(p);
    if (!path) return -5;
    Dir *d = open_dir(path);
    free(path);
    if (!d) return -failure();
    int64_t l = kova_list_new(1);
    const char *name;
    while ((name = read_dir(d))) {
        if (!strcmp(name, ".") || !strcmp(name, "..")) continue;
        size_t n = strlen(name);
        if (!*name || !valid_utf8((unsigned char *)name, n)) {
            for (int64_t i = 0; i < kova_list_length(l); i++) kova_str_free(kova_list_load(l, i, 0));
            kova_list_free(l);
            close_dir(d);
            return -4;
        }
        kova_list_store(l, kova_list_grow(l), 0, kova_str_new(name, n));
    }
    close_dir(d);
    qsort(((List *)l)->slots, ((List *)l)->length, sizeof(int64_t), by_bytes);
    return l;
}

// Like `mkdir -p`: the missing parents too; a directory already there is fine.
int64_t kova_make_dir(int64_t p) {
    char *path = c_path(p);
    if (!path) return -5;
    if (!*path) {
        free(path);
        return -1;
    }
    int64_t result = 0;
    for (char *c = path + 1;; c++) {
        if (*c != '/' && *c != SLASH && *c) continue;
        char end = *c;
        *c = 0;
        int made = make_one(path) == 0, e = errno;
        // `C:` on Windows cannot be made but is there.
        if (kind_of(path) != 2) {
            errno = e;
            result = made || e == EEXIST ? -5 : -failure();
        }
        *c = end;
        if (result || !end) break;
    }
    free(path);
    return result;
}

int64_t kova_remove_file(int64_t p) {
    char *path = c_path(p);
    if (!path) return -5;
    int64_t result = 0;
    if (kind_of(path) == 2) result = -3;
    else if (remove_one(path) != 0) result = -failure();
    free(path);
    return result;
}

// ---- String methods that look for a text or make a List (src/interp.rs does the same) ----

// The spaces of `trim` and `words`: Rust's `is_ascii_whitespace`.
static int is_space(char c) {
    return c == ' ' || c == '\t' || c == '\n' || c == '\f' || c == '\r';
}

int64_t kova_str_trim(int64_t a) {
    String *x = (String *)a;
    int64_t i = 0, j = x->length;
    while (i < j && is_space(x->bytes[i])) i++;
    while (j > i && is_space(x->bytes[j - 1])) j--;
    return kova_str_new(x->bytes + i, j - i);
}

// Where `y` starts in `x`, from byte `from` on; -1 if nowhere.
static int64_t find(String *x, String *y, int64_t from) {
    for (int64_t i = from; i + y->length <= x->length; i++)
        if (memcmp(x->bytes + i, y->bytes, y->length) == 0) return i;
    return -1;
}

int64_t kova_str_contains(int64_t a, int64_t b) {
    return find((String *)a, (String *)b, 0) >= 0;
}

int64_t kova_str_starts_with(int64_t a, int64_t b) {
    String *x = (String *)a, *y = (String *)b;
    return y->length <= x->length && memcmp(x->bytes, y->bytes, y->length) == 0;
}

int64_t kova_str_ends_with(int64_t a, int64_t b) {
    String *x = (String *)a, *y = (String *)b;
    return y->length <= x->length && memcmp(x->bytes + x->length - y->length, y->bytes, y->length) == 0;
}

// `old` is never empty (src/kir.rs checks it before).
int64_t kova_str_replace(int64_t a, int64_t b, int64_t c) {
    String *x = (String *)a, *old = (String *)b, *new = (String *)c;
    int64_t count = 0, i = 0, j;
    while ((j = find(x, old, i)) >= 0) count++, i = j + old->length;
    String *s = new_string(x->length + count * (new->length - old->length));
    char *out = s->bytes;
    for (i = 0; (j = find(x, old, i)) >= 0; i = j + old->length) {
        memcpy(out, x->bytes + i, j - i);
        out += j - i;
        memcpy(out, new->bytes, new->length);
        out += new->length;
    }
    memcpy(out, x->bytes + i, x->length - i);
    return (int64_t)s;
}

static void push(int64_t l, int64_t v) {
    kova_list_store(l, kova_list_grow(l), 0, v);
}

// `separator` is never empty (src/kir.rs checks it before).
int64_t kova_str_split(int64_t a, int64_t b) {
    String *x = (String *)a, *y = (String *)b;
    int64_t l = kova_list_new(1), i = 0, j;
    for (; (j = find(x, y, i)) >= 0; i = j + y->length) push(l, kova_str_new(x->bytes + i, j - i));
    push(l, kova_str_new(x->bytes + i, x->length - i));
    return l;
}

int64_t kova_str_words(int64_t a) {
    String *x = (String *)a;
    int64_t l = kova_list_new(1), i = 0;
    while (i < x->length) {
        while (i < x->length && is_space(x->bytes[i])) i++;
        int64_t start = i;
        while (i < x->length && !is_space(x->bytes[i])) i++;
        if (i > start) push(l, kova_str_new(x->bytes + start, i - start));
    }
    return l;
}

// The Unicode code of each character (the String is valid UTF-8).
int64_t kova_str_chars(int64_t a) {
    String *x = (String *)a;
    int64_t l = kova_list_new(1);
    for (int64_t i = 0; i < x->length;) {
        unsigned char c = x->bytes[i];
        int n = c < 0x80 ? 1 : c < 0xE0 ? 2 : c < 0xF0 ? 3 : 4;
        int64_t code = n == 1 ? c : c & (0x7F >> n);
        for (int k = 1; k < n; k++) code = (code << 6) | (x->bytes[i + k] & 0x3F);
        push(l, code);
        i += n;
    }
    return l;
}

// ---- More String methods (Part 4, "Standard library v2"); src/interp.rs does the same ----

// How many characters the first `bytes` bytes of `x` hold.
static int64_t chars_in(String *x, int64_t bytes) {
    int64_t n = 0;
    for (int64_t i = 0; i < bytes; i++) n += ((unsigned char)x->bytes[i] & 0xC0) != 0x80;
    return n;
}

// Where character number `k` starts in `x` (its length for `k` = the number of characters).
static int64_t byte_of(String *x, int64_t k) {
    int64_t i = 0;
    for (; i < x->length; i++)
        if (((unsigned char)x->bytes[i] & 0xC0) != 0x80 && k-- == 0) break;
    return i;
}

// `s.find(part)`: the number of the character where `part` starts first, -1 if nowhere.
int64_t kova_str_find(int64_t a, int64_t b) {
    String *x = (String *)a;
    int64_t i = find(x, (String *)b, 0);
    return i < 0 ? -1 : chars_in(x, i);
}

// `s[from..to]`: characters `from` to `to` (without it), checked before by src/kir.rs.
int64_t kova_str_slice(int64_t a, int64_t from, int64_t to) {
    String *x = (String *)a;
    int64_t i = byte_of(x, from), j = byte_of(x, to);
    return kova_str_new(x->bytes + i, j - i);
}

// `s.repeat(n)`: `s` `n` times; nothing for `n` <= 0.
int64_t kova_str_repeat(int64_t a, int64_t n) {
    String *x = (String *)a;
    if (n <= 0 || x->length == 0) return kova_str_new("", 0);
    if (x->length > INT64_MAX / n) abort();
    char *bytes = malloc(x->length * n + 1);
    if (!bytes) abort();
    for (int64_t k = 0; k < n; k++) memcpy(bytes + k * x->length, x->bytes, x->length);
    int64_t r = kova_str_new(bytes, x->length * n);
    free(bytes);
    return r;
}

// `words.join(", ")`: the Strings of the List with `sep` between them.
int64_t kova_str_join(int64_t l, int64_t sep) {
    String *s = (String *)sep;
    int64_t n = kova_list_length(l), size = 0;
    for (int64_t k = 0; k < n; k++) size += ((String *)kova_list_load(l, k, 0))->length + (k ? s->length : 0);
    char *bytes = malloc(size + 1), *at = bytes;
    if (!bytes) abort();
    for (int64_t k = 0; k < n; k++) {
        String *w = (String *)kova_list_load(l, k, 0);
        if (k) at = memcpy(at, s->bytes, s->length), at += s->length;
        memcpy(at, w->bytes, w->length);
        at += w->length;
    }
    int64_t r = kova_str_new(bytes, size);
    free(bytes);
    return r;
}

// The capital (`upper`) or small letter of `c`, for the Latin, Greek and Cyrillic alphabets;
// any other character stays. The same table as `case_of` in src/kir.rs.
// ponytail: simple rules, no table of all of Unicode (`ß` stays `ß`, Armenian, Georgian… stay).
static uint32_t case_of(uint32_t c, int upper) {
    if (upper) {
        if ((c >= 'a' && c <= 'z') || (c >= 0xE0 && c <= 0xFE && c != 0xF7) || (c >= 0x3B1 && c <= 0x3C9 && c != 0x3C2) || (c >= 0x430 && c <= 0x44F)) return c - 32;
        if (c == 0xFF) return 0x178;
        if (c == 0x3C2) return 0x3A3;
        if (c >= 0x450 && c <= 0x45F) return c - 80;
        if (((c >= 0x100 && c <= 0x12F) || (c >= 0x132 && c <= 0x137) || (c >= 0x14A && c <= 0x177)) && c % 2 == 1) return c - 1;
        if (((c >= 0x139 && c <= 0x148) || (c >= 0x179 && c <= 0x17E)) && c % 2 == 0) return c - 1;
    } else {
        if ((c >= 'A' && c <= 'Z') || (c >= 0xC0 && c <= 0xDE && c != 0xD7) || (c >= 0x391 && c <= 0x3A9 && c != 0x3A2) || (c >= 0x410 && c <= 0x42F)) return c + 32;
        if (c == 0x178) return 0xFF;
        if (c >= 0x400 && c <= 0x40F) return c + 80;
        if (((c >= 0x100 && c <= 0x12F) || (c >= 0x132 && c <= 0x137) || (c >= 0x14A && c <= 0x177)) && c % 2 == 0) return c + 1;
        if (((c >= 0x139 && c <= 0x148) || (c >= 0x179 && c <= 0x17E)) && c % 2 == 1) return c + 1;
    }
    return c;
}

static int64_t change_case(int64_t a, int upper) {
    String *x = (String *)a;
    // A capital may take more bytes than its small letter (ÿ, 2 bytes → Ÿ, 2 bytes; ı is left out):
    // at most 3 bytes per byte is always enough.
    char *bytes = malloc(3 * x->length + 1);
    if (!bytes) abort();
    int64_t size = 0;
    for (int64_t i = 0; i < x->length;) {
        unsigned char c = x->bytes[i];
        int n = c < 0x80 ? 1 : c < 0xE0 ? 2 : c < 0xF0 ? 3 : 4;
        uint32_t code = n == 1 ? c : c & (0x7F >> n);
        for (int k = 1; k < n; k++) code = (code << 6) | (x->bytes[i + k] & 0x3F);
        code = case_of(code, upper);
        if (code < 0x80) bytes[size++] = code;
        else if (code < 0x800) bytes[size++] = 0xC0 | code >> 6, bytes[size++] = 0x80 | (code & 0x3F);
        else if (code < 0x10000) bytes[size++] = 0xE0 | code >> 12, bytes[size++] = 0x80 | (code >> 6 & 0x3F), bytes[size++] = 0x80 | (code & 0x3F);
        else bytes[size++] = 0xF0 | code >> 18, bytes[size++] = 0x80 | (code >> 12 & 0x3F), bytes[size++] = 0x80 | (code >> 6 & 0x3F), bytes[size++] = 0x80 | (code & 0x3F);
        i += n;
    }
    int64_t r = kova_str_new(bytes, size);
    free(bytes);
    return r;
}

int64_t kova_str_to_upper(int64_t a) { return change_case(a, 1); }
int64_t kova_str_to_lower(int64_t a) { return change_case(a, 0); }

// `s.to_float`: an optional `-`, digits, then maybe `.` and digits, then maybe `e`, a sign and
// digits; the same rule as `parse_float` in src/kir.rs. Too big (infinite) is not a Float either.
static int parse_float(int64_t a, double *v) {
    String *x = (String *)a;
    int64_t i = 0, n = x->length, d;
    const char *b = x->bytes;
    if (i < n && b[i] == '-') i++;
    for (d = i; i < n && isdigit((unsigned char)b[i]); i++) {}
    if (i == d) return 0;
    if (i < n && b[i] == '.') {
        for (d = ++i; i < n && isdigit((unsigned char)b[i]); i++) {}
        if (i == d) return 0;
    }
    if (i < n && (b[i] == 'e' || b[i] == 'E')) {
        i++;
        if (i < n && (b[i] == '+' || b[i] == '-')) i++;
        for (d = i; i < n && isdigit((unsigned char)b[i]); i++) {}
        if (i == d) return 0;
    }
    if (i != n) return 0;
    char *text = malloc(n + 1);
    if (!text) abort();
    memcpy(text, b, n);
    text[n] = 0;
    *v = strtod(text, NULL);
    free(text);
    return !isinf(*v);
}

int64_t kova_str_is_float(int64_t a) {
    double v;
    return parse_float(a, &v);
}

// Its bits (src/kir.rs turns them back into a Float).
int64_t kova_str_to_float(int64_t a) {
    double v = 0;
    if (!parse_float(a, &v)) v = 0;
    int64_t bits;
    memcpy(&bits, &v, sizeof bits);
    return bits;
}

// How a value is written, one function per `Show` of src/kir.rs: the generated code gives the
// address of the one it needs, so a program that never shows a Float doesn't carry their formatting.
typedef void (*Writer)(Out *o, int64_t value);

void kova_show_int(Out *o, int64_t value) { put_int(o, value); }
void kova_show_bool(Out *o, int64_t value) { put_text(o, value ? "true" : "false"); }
void kova_show_float(Out *o, int64_t value) {
    double x;
    memcpy(&x, &value, sizeof x);
    write_float(o, x);
}
void kova_show_char(Out *o, int64_t value) { write_char(o, (uint32_t)value); }
void kova_show_string(Out *o, int64_t value) { put(o, ((String *)value)->bytes, ((String *)value)->length); }
void kova_show_site(Out *o, int64_t value) {
    put_text(o, kova_files[value >> 32]);
    put_char(o, ':');
    put_int(o, value & 0xffffffff);
}

// The text of a value, as `print` writes it (`"{x}"`).
int64_t kova_str_format(int64_t value, int64_t show) {
    Out o = {0};
    ((Writer)show)(&o, value);
    int64_t s = kova_str_new(o.bytes, o.n);
    free(o.bytes);
    return s;
}

void kova_print(int64_t value, int64_t show, int64_t newline) {
    Out o = {.f = stdout};
    ((Writer)show)(&o, value);
    if (newline) putchar('\n');
}

// `fault` = the number of its text. Text 0 is `error_prefix` ("error: ").
void kova_fault(int64_t fault, int64_t line, int64_t col) {
    fflush(stdout);
    fprintf(stderr, "%s%s\n  --> %s:%lld:%lld\n", text(0), text(fault), kova_files[line >> 32], (long long)(line & 0xffffffff),
            (long long)col);
    exit(101);
}

// The message of a broken contract comes in pieces (src/kir.rs, `Piece`),
// then `kova_fail` stops the program.
void kova_write_text(const char *text, int64_t n) {
    fflush(stdout);
    fwrite(text, 1, n, stderr);
}

void kova_write_label(int64_t i) {
    fflush(stdout);
    fputs(text(i), stderr);
}

void kova_write_value(int64_t value, int64_t show) {
    Out o = {.f = stderr};
    ((Writer)show)(&o, value);
}

void kova_fail(void) {
    exit(101);
}

// With KOVA_LEAKS set (the test runner sets it): a String never freed is an error (code 102);
// `KOVA_LEAKS=count` also prints how many were made. Same as `leaks` in src/interp.rs.
static int leaks(void) {
    const char *mode = getenv("KOVA_LEAKS");
    if (!mode) return 0;
    fflush(stdout);
    if (strcmp(mode, "count") == 0) fprintf(stderr, "%s%lld\n", text(LEAK_ALLOCATED), (long long)allocated);
    if (live == 0) return 0;
    fprintf(stderr, "%s%s%lld\n", text(0), text(LEAK_LIVE), (long long)live);
    return 102;
}

// `args`: the words after the program's name.
static int nb_args;
static char **arg_texts;

int64_t kova_args(void) {
    int64_t l = kova_list_new(1);
    for (int i = 1; i < nb_args; i++) push(l, kova_str_new(arg_texts[i], strlen(arg_texts[i])));
    return l;
}

// ---- Time and chance (src/interp.rs does the same) ----

// The nanoseconds since 1970 (UTC).
static uint64_t clock_now(void) {
#ifdef _WIN32
    FILETIME t; // in 100 ns since 1601
    GetSystemTimePreciseAsFileTime(&t);
    return ((uint64_t)t.dwHighDateTime << 32 | t.dwLowDateTime) * 100 - 11644473600000000000u;
#else
    struct timespec t;
    clock_gettime(CLOCK_REALTIME, &t);
    return (uint64_t)t.tv_sec * 1000000000u + (uint64_t)t.tv_nsec;
#endif
}

// `now`: the seconds since 1970 (UTC), as a Float's bits.
int64_t kova_now(void) {
    uint64_t t = clock_now();
    double s = (double)(t / 1000000000u) + (double)(t % 1000000000u) / 1e9;
    int64_t bits;
    memcpy(&bits, &s, sizeof bits);
    return bits;
}

// `sleep(seconds)`, a Float's bits: what `write` left is shown first; 0 or less waits nothing.
int64_t kova_sleep(int64_t bits) {
    double s;
    memcpy(&s, &bits, sizeof s);
    fflush(stdout);
    if (s > 0 && s < 1e9) {
#ifdef _WIN32
        // ponytail: whole milliseconds, up to 49 days at a time.
        Sleep(s < 4e6 ? (DWORD)(s * 1000) : 4000000000u);
#else
        struct timespec t = { (time_t)s, (long)((s - (double)(time_t)s) * 1e9) };
        while (nanosleep(&t, &t) != 0 && errno == EINTR) {}
#endif
    }
    return 0;
}

// The random numbers: splitmix64, started from `KOVA_SEED` (a number) if it is set, so that a
// run can be made again (`kova run` gives the same numbers), else from the clock.
static uint64_t chance;
static int chance_started;

static uint64_t next_chance(void) {
    uint64_t z = chance += 0x9E3779B97F4A7C15u;
    z = (z ^ z >> 30) * 0xBF58476D1CE4E5B9u;
    z = (z ^ z >> 27) * 0x94D049BB133111EBu;
    return z ^ z >> 31;
}

// `random(from..to)`: `to` excluded, `from < to` checked before by src/kir.rs. Draws again
// above the last whole multiple of the range's size, so that each number is as likely.
int64_t kova_random(int64_t from, int64_t to) {
    if (!chance_started) {
        const char *s = getenv("KOVA_SEED");
        char *end = NULL;
        errno = 0;
        unsigned long long seed = s && isdigit((unsigned char)*s) ? strtoull(s, &end, 10) : 0;
        if (end && !*end && errno == 0) chance = seed;
        else {
#ifdef _WIN32
            uint64_t pid = (uint64_t)_getpid();
#else
            uint64_t pid = (uint64_t)getpid();
#endif
            chance = clock_now() ^ pid << 32;
        }
        chance_started = 1;
    }
    uint64_t n = (uint64_t)to - (uint64_t)from, limit = UINT64_MAX - UINT64_MAX % n, x;
    do x = next_chance(); while (x >= limit);
    return (int64_t)((uint64_t)from + x % n);
}

// `exit(code)`: what is still alive is not freed, and not counted as a leak (src/interp.rs too).
void kova_exit(int64_t code) {
    fflush(stdout);
    exit((int)code);
}

int main(int argc, char **argv) {
#ifdef _WIN32
    // The same bytes as `kova run`: `\n` stays `\n`, and the console reads them as UTF-8.
    _setmode(_fileno(stdin), _O_BINARY);
    _setmode(_fileno(stdout), _O_BINARY);
    _setmode(_fileno(stderr), _O_BINARY);
    SetConsoleOutputCP(CP_UTF8);
    SetConsoleCP(CP_UTF8);
    // The words as typed, in UTF-8 (`argv` would be in the old code page).
    wchar_t **words = CommandLineToArgvW(GetCommandLineW(), &argc);
    argv = malloc(argc * sizeof *argv);
    if (!words || !argv) abort();
    for (int i = 0; i < argc; i++) {
        int n = WideCharToMultiByte(CP_UTF8, 0, words[i], -1, NULL, 0, NULL, NULL);
        if (!(argv[i] = malloc(n))) abort();
        WideCharToMultiByte(CP_UTF8, 0, words[i], -1, argv[i], n, NULL, NULL);
    }
#endif
    nb_args = argc;
    arg_texts = argv;
    kova_main();
    return leaks();
}
